export const boot = createServerFn({ method: "POST" })
  .inputValidator((d) => z.object({ label: z.string().min(1).max(80) }).parse(d))
  .handler(async ({ data }) => {
    const slug = data.label.toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 40) || "svc";
